// api/db.js - Conexión oficial a Neon PostgreSQL Serverless
import { neon } from '@neondatabase/serverless';

export function getDb() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.warn('DATABASE_URL no configurada. Usando modo demostración.');
    return null;
  }
  return neon(databaseUrl);
}

// api/resumen.js - Endpoint de consulta completa y contabilidad para Vercel + Neon
import { getDb } from './db.js';

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }

  const sql = getDb();
  if (!sql) {
    return res.status(500).json({ error: 'DATABASE_URL no configurada' });
  }

  try {
    // 1. Obras con conteo de operarios asignados
    const obras = await sql`
      SELECT o.*,
             COUNT(DISTINCT po.personal_id) as total_operarios_asignados
      FROM obras o
      LEFT JOIN personal_obras po ON po.obra_id = o.id
      GROUP BY o.id
      ORDER BY o.id ASC;
    `;

    // 2. Personales con múltiples obras asociadas (Muchos a Muchos)
    const personales = await sql`
      SELECT p.id, p.nombre, p.cargo, p.jornal_diario, p.telefono, p.activo,
             COALESCE(SUM(av.vale_adelanto), 0) as total_vales,
             COALESCE(
               json_agg(
                 json_build_object('id', o.id, 'nombre', o.nombre)
               ) FILTER (WHERE o.id IS NOT NULL),
               '[]'
             ) as obras_asignadas,
             COALESCE(
               array_agg(o.id) FILTER (WHERE o.id IS NOT NULL),
               '{}'
             ) as obras_ids
      FROM personales p
      LEFT JOIN personal_obras po ON po.personal_id = p.id
      LEFT JOIN obras o ON po.obra_id = o.id
      LEFT JOIN asistencias_vales av ON av.personal_id = p.id
      GROUP BY p.id, p.nombre, p.cargo, p.jornal_diario, p.telefono, p.activo
      ORDER BY p.id ASC;
    `;

    // 3. Vales detallados individuales
    const vales_detalle = await sql`
      SELECT av.id, av.personal_id, p.nombre as personal_nombre, av.obra_id, o.nombre as obra_nombre,
             av.fecha, av.vale_adelanto, av.observacion, av.estado
      FROM asistencias_vales av
      JOIN personales p ON av.personal_id = p.id
      LEFT JOIN obras o ON av.obra_id = o.id
      ORDER BY av.id DESC;
    `;

    // 4. Materiales y remisiones
    const materiales = await sql`
      SELECT m.*, o.nombre as obra
      FROM materiales m
      LEFT JOIN obras o ON m.obra_id = o.id
      ORDER BY m.fecha_entrega ASC;
    `;

    // 5. Servicios de Bobcat
    const bobcat = await sql`
      SELECT * FROM bobcat_servicios
      ORDER BY fecha_servicio DESC;
    `;

    // 6. Registro de Actividad
    let actividad = [];
    try {
      actividad = await sql`SELECT * FROM actividad_whatsapp ORDER BY fecha DESC LIMIT 20;`;
    } catch (e) {
      console.warn('Tabla actividad:', e.message);
    }

    // 7. Balance y Contabilidad Detallada
    let totalValesSemana = 0;
    let totalJornalesEstimados = 0;
    personales.forEach(p => {
      const val = Number(p.total_vales || 0);
      totalValesSemana += val;
      totalJornalesEstimados += (Number(p.jornal_diario || 150000) * 5); // 5 días de jornal
    });

    let totalBobcatCobrado = 0;
    let totalBobcatPendiente = 0;
    bobcat.forEach(b => {
      const fact = Number(b.total_facturado || 0);
      if (b.estado === 'finalizado_cobrado') {
        totalBobcatCobrado += fact;
      } else {
        totalBobcatPendiente += fact;
      }
    });

    const totalIngresos = totalBobcatCobrado + totalBobcatPendiente;
    const totalEgresos = totalJornalesEstimados; // Jornales brutos a liquidar
    const saldoNeto = totalIngresos - totalEgresos;

    return res.status(200).json({
      modo: 'neon_postgres_en_vivo',
      obras,
      personales,
      vales_detalle,
      materiales,
      bobcat,
      actividad,
      contabilidad: {
        total_ingresos: totalIngresos,
        total_bobcat_cobrado: totalBobcatCobrado,
        total_bobcat_pendiente: totalBobcatPendiente,
        total_egresos_jornales: totalJornalesEstimados,
        total_vales_adelantados: totalValesSemana,
        saldo_liquido_sabado: (totalJornalesEstimados - totalValesSemana),
        balance_neto_operativo: saldoNeto
      }
    });
  } catch (error) {
    console.error('Error consultando Neon:', error);
    return res.status(500).json({ error: error.message });
  }
}

// api/acciones.js - CRUD interactivo integral (Crear, Editar, Eliminar) conectado a Neon
import { getDb } from './db.js';

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') return res.status(200).end();
  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });

  const sql = getDb();
  if (!sql) {
    return res.status(500).json({ error: 'DATABASE_URL no configurada' });
  }

  const { accion, data } = req.body || {};

  try {
    // ==========================================
    // 1. MÓDULO OBRAS
    // ==========================================
    if (accion === 'crear_obra') {
      const { nombre, ubicacion, etapa_actual, porcentaje_avance } = data;
      await sql`
        INSERT INTO obras (nombre, ubicacion, etapa_actual, porcentaje_avance, estado)
        VALUES (${nombre}, ${ubicacion}, ${etapa_actual || 'Inicio'}, ${porcentaje_avance || 0}, 'activa')
      `;
      return res.status(200).json({ ok: true, mensaje: 'Obra creada exitosamente' });
    }

    if (accion === 'editar_obra') {
      const { id, nombre, ubicacion, etapa_actual, porcentaje_avance, estado } = data;
      await sql`
        UPDATE obras
        SET nombre = ${nombre}, ubicacion = ${ubicacion}, etapa_actual = ${etapa_actual},
            porcentaje_avance = ${porcentaje_avance}, estado = ${estado || 'activa'}
        WHERE id = ${id}
      `;
      return res.status(200).json({ ok: true, mensaje: 'Obra actualizada correctamente' });
    }

    if (accion === 'eliminar_obra') {
      const { id } = data;
      await sql`DELETE FROM obras WHERE id = ${id}`;
      return res.status(200).json({ ok: true, mensaje: 'Obra eliminada del sistema' });
    }

    // ==========================================
    // 2. MÓDULO PERSONALES (Con N a N Obras)
    // ==========================================
    if (accion === 'crear_personal') {
      const { nombre, cargo, jornal_diario, telefono, obras_ids } = data;
      const result = await sql`
        INSERT INTO personales (nombre, cargo, jornal_diario, telefono, activo)
        VALUES (${nombre}, ${cargo}, ${jornal_diario || 150000}, ${telefono || ''}, true)
        RETURNING id;
      `;
      const personalId = result[0].id;

      // Asignar en personal_obras
      if (Array.isArray(obras_ids) && obras_ids.length > 0) {
        for (const oId of obras_ids) {
          await sql`
            INSERT INTO personal_obras (personal_id, obra_id)
            VALUES (${personalId}, ${oId})
            ON CONFLICT DO NOTHING;
          `;
        }
      }
      return res.status(200).json({ ok: true, mensaje: 'Personal registrado y asignado a obras' });
    }

    if (accion === 'editar_personal') {
      const { id, nombre, cargo, jornal_diario, telefono, activo, obras_ids } = data;
      await sql`
        UPDATE personales
        SET nombre = ${nombre}, cargo = ${cargo}, jornal_diario = ${jornal_diario},
            telefono = ${telefono || ''}, activo = ${activo !== false}
        WHERE id = ${id}
      `;

      // Sincronizar obras asignadas
      await sql`DELETE FROM personal_obras WHERE personal_id = ${id}`;
      if (Array.isArray(obras_ids) && obras_ids.length > 0) {
        for (const oId of obras_ids) {
          await sql`
            INSERT INTO personal_obras (personal_id, obra_id)
            VALUES (${id}, ${oId})
            ON CONFLICT DO NOTHING;
          `;
        }
      }
      return res.status(200).json({ ok: true, mensaje: 'Personal y asignación de obras actualizados' });
    }

    if (accion === 'eliminar_personal') {
      const { id } = data;
      await sql`DELETE FROM personales WHERE id = ${id}`;
      return res.status(200).json({ ok: true, mensaje: 'Personal eliminado' });
    }

    // ==========================================
    // 3. MÓDULO VALES / ASISTENCIAS
    // ==========================================
    if (accion === 'registrar_vale') {
      const { personal_id, obra_id, vale, observacion } = data;
      await sql`
        INSERT INTO asistencias_vales (personal_id, obra_id, fecha, estado, vale_adelanto, observacion)
        VALUES (${personal_id}, ${obra_id || null}, CURRENT_DATE, 'presente', ${vale || 0}, ${observacion || 'Vale manual'})
      `;
      return res.status(200).json({ ok: true, mensaje: 'Vale registrado en Neon' });
    }

    if (accion === 'editar_vale') {
      const { id, vale_adelanto, observacion } = data;
      await sql`
        UPDATE asistencias_vales
        SET vale_adelanto = ${vale_adelanto}, observacion = ${observacion || ''}
        WHERE id = ${id}
      `;
      return res.status(200).json({ ok: true, mensaje: 'Vale modificado' });
    }

    if (accion === 'eliminar_vale') {
      const { id } = data;
      await sql`DELETE FROM asistencias_vales WHERE id = ${id}`;
      return res.status(200).json({ ok: true, mensaje: 'Vale eliminado y restituido a la liquidación' });
    }

    // ==========================================
    // 4. MÓDULO BOBCAT
    // ==========================================
    if (accion === 'crear_bobcat') {
      const { cliente, telefono, zona, fecha, horas, tarifa_hora, costo_traslado, operador } = data;
      const tarifa = Number(tarifa_hora || 250000);
      const flete = Number(costo_traslado || 250000);
      const horasNum = Number(horas || 4);
      const total = (horasNum * tarifa) + flete;

      await sql`
        INSERT INTO bobcat_servicios (
          cliente, telefono_cliente, zona_destino, fecha_servicio,
          horas_pactadas, horas_reales, tarifa_hora, costo_traslado, total_facturado, operador, estado
        ) VALUES (
          ${cliente}, ${telefono || ''}, ${zona}, ${fecha || new Date().toISOString()},
          ${horasNum}, 0, ${tarifa}, ${flete}, ${total}, ${operador || 'Ramón'}, 'agendado'
        )
      `;
      return res.status(200).json({ ok: true, mensaje: 'Servicio Bobcat agendado' });
    }

    if (accion === 'editar_bobcat') {
      const { id, cliente, telefono, zona, fecha, horas_pactadas, horas_reales, tarifa_hora, costo_traslado, estado, notas } = data;
      const horasFinales = Number(horas_reales > 0 ? horas_reales : horas_pactadas);
      const tarifa = Number(tarifa_hora || 250000);
      const flete = Number(costo_traslado || 250000);
      const total = (horasFinales * tarifa) + flete;

      await sql`
        UPDATE bobcat_servicios
        SET cliente = ${cliente}, telefono_cliente = ${telefono || ''}, zona_destino = ${zona},
            fecha_servicio = ${fecha}, horas_pactadas = ${horas_pactadas}, horas_reales = ${horas_reales || 0},
            tarifa_hora = ${tarifa}, costo_traslado = ${flete}, total_facturado = ${total},
            estado = ${estado || 'agendado'}, notas_operador = ${notas || ''}
        WHERE id = ${id}
      `;
      return res.status(200).json({ ok: true, mensaje: 'Servicio Bobcat actualizado' });
    }

    if (accion === 'cerrar_bobcat_ramon') {
      const { servicio_id, horas_reales, notas } = data;
      const horasNum = Number(horas_reales);
      const totalFinal = (horasNum * 250000) + 250000;

      await sql`
        UPDATE bobcat_servicios
        SET horas_reales = ${horasNum}, total_facturado = ${totalFinal}, estado = 'finalizado_cobrado', notas_operador = ${notas || 'Cierre verificado'}
        WHERE id = ${servicio_id}
      `;
      return res.status(200).json({ ok: true, mensaje: 'Horómetro de Ramón liquidado exitosamente' });
    }

    if (accion === 'eliminar_bobcat') {
      const { id } = data;
      await sql`DELETE FROM bobcat_servicios WHERE id = ${id}`;
      return res.status(200).json({ ok: true, mensaje: 'Servicio de Bobcat eliminado' });
    }

    // ==========================================
    // 5. MÓDULO MATERIALES
    // ==========================================
    if (accion === 'registrar_material') {
      const { obra_id, material, cantidad, proveedor, fecha_entrega, responsable_recepcion } = data;
      await sql`
        INSERT INTO materiales (obra_id, material, cantidad, proveedor, fecha_entrega, responsable_recepcion, estado)
        VALUES (${obra_id || null}, ${material}, ${cantidad}, ${proveedor}, ${fecha_entrega || new Date().toISOString()}, ${responsable_recepcion || 'Encargado'}, 'programado')
      `;
      return res.status(200).json({ ok: true, mensaje: 'Material agendado' });
    }

    if (accion === 'editar_material') {
      const { id, obra_id, material, cantidad, proveedor, fecha_entrega, responsable_recepcion, estado, remision_nro } = data;
      await sql`
        UPDATE materiales
        SET obra_id = ${obra_id || null}, material = ${material}, cantidad = ${cantidad},
            proveedor = ${proveedor}, fecha_entrega = ${fecha_entrega}, responsable_recepcion = ${responsable_recepcion},
            estado = ${estado || 'programado'}, remision_nro = ${remision_nro || ''}
        WHERE id = ${id}
      `;
      return res.status(200).json({ ok: true, mensaje: 'Material actualizado' });
    }

    if (accion === 'marcar_material_recibido') {
      const { material_id, remision_nro } = data;
      await sql`
        UPDATE materiales
        SET estado = 'recibido', remision_nro = ${remision_nro || 'S/N'}
        WHERE id = ${material_id}
      `;
      return res.status(200).json({ ok: true, mensaje: 'Material marcado como recibido' });
    }

    if (accion === 'eliminar_material') {
      const { id } = data;
      await sql`DELETE FROM materiales WHERE id = ${id}`;
      return res.status(200).json({ ok: true, mensaje: 'Registro de material eliminado' });
    }

    return res.status(400).json({ error: 'Acción no reconocida' });
  } catch (error) {
    console.error('Error ejecutando acción:', error);
    return res.status(500).json({ error: error.message });
  }
}

// api/webhook-whatsapp.js - Endpoint para recibir datos procesados por n8n e insertarlos en Neon
import { getDb } from './db.js';

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') return res.status(200).end();
  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });

  const sql = getDb();
  const body = req.body || {};
  const { tipo, data, remitente, mensaje_original } = body;

  if (!sql) {
    return res.status(200).json({ ok: true, mensaje: 'Simulación exitosa (sin DATABASE_URL configurada)' });
  }

  try {
    if (tipo === 'vale_asistencia') {
      // Registrar vale o asistencia
      await sql`
        INSERT INTO asistencias_vales (personal_id, obra_id, fecha, estado, vale_adelanto, observacion)
        VALUES (${data.personal_id}, ${data.obra_id}, CURRENT_DATE, ${data.estado || 'presente'}, ${data.vale || 0}, ${data.observacion || ''})
      `;
      await sql`
        INSERT INTO actividad_whatsapp (remitente, tipo_evento, mensaje_original, resumen_accion)
        VALUES (
          ${remitente || 'WhatsApp (Obra)'},
          'asistencia_vale',
          ${mensaje_original || `Vale de ${data.vale} Gs. registrado por WhatsApp`},
          ${`Registrado vale para personal #${data.personal_id} en obra #${data.obra_id}`}
        )
      `;
      return res.status(200).json({ ok: true, mensaje: 'Vale / asistencia registrada en Neon' });
    }

    if (tipo === 'reserva_bobcat') {
      // Registrar nueva reserva de Bobcat
      const total = (Number(data.horas || 4) * 250000) + 250000;
      await sql`
        INSERT INTO bobcat_servicios (cliente, telefono_cliente, zona_destino, fecha_servicio, horas_pactadas, tarifa_hora, costo_traslado, total_facturado, estado)
        VALUES (${data.cliente}, ${data.telefono || ''}, ${data.zona}, ${data.fecha || new Date().toISOString()}, ${data.horas || 4}, 250000, 250000, ${total}, 'agendado')
      `;
      await sql`
        INSERT INTO actividad_whatsapp (remitente, tipo_evento, mensaje_original, resumen_accion)
        VALUES (
          ${remitente || 'WhatsApp (Cliente Bobcat)'},
          'reserva_bobcat',
          ${mensaje_original || `Pedido de Bobcat por WhatsApp: ${data.cliente}`},
          ${`Reserva agendada en ${data.zona}. ${data.horas || 4} hs.`}
        )
      `;
      return res.status(200).json({ ok: true, mensaje: 'Reserva Bobcat guardada en Neon' });
    }

    if (tipo === 'cierre_horas_ramon') {
      // Ramón reporta horas reales trabajadas
      const horasReales = Number(data.horas_reales);
      const totalFinal = (horasReales * 250000) + 250000;
      await sql`
        UPDATE bobcat_servicios
        SET horas_reales = ${horasReales}, total_facturado = ${totalFinal}, estado = 'finalizado_cobrado', notas_operador = ${data.notas || 'Cierre por WhatsApp'}
        WHERE id = ${data.servicio_id}
      `;
      await sql`
        INSERT INTO actividad_whatsapp (remitente, tipo_evento, mensaje_original, resumen_accion)
        VALUES (
          'Operador Ramón (WhatsApp)',
          'horas_ramon',
          ${mensaje_original || `Ramón reportó ${horasReales} horas reales de horómetro`},
          ${`Servicio #${data.servicio_id} cobrado y finalizado: ${totalFinal.toLocaleString('es-PY')} Gs.`}
        )
      `;
      return res.status(200).json({ ok: true, mensaje: 'Horas y liquidación de Ramón actualizadas en Neon' });
    }

    if (tipo === 'recepcion_material') {
      await sql`
        INSERT INTO materiales (obra_id, material, cantidad, proveedor, fecha_entrega, responsable_recepcion, estado, remision_nro)
        VALUES (${data.obra_id || null}, ${data.material}, ${data.cantidad}, ${data.proveedor || 'Proveedor'}, ${data.fecha_entrega || new Date().toISOString()}, ${data.responsable || 'Encargado'}, ${data.estado || 'programado'}, ${data.remision_nro || ''})
      `;
      await sql`
        INSERT INTO actividad_whatsapp (remitente, tipo_evento, mensaje_original, resumen_accion)
        VALUES (
          ${remitente || 'WhatsApp (Proveedor)'},
          'material_recepcion',
          ${mensaje_original || `Entrega de material reportada por WhatsApp`},
          ${`Agendada entrega de ${data.material} (${data.cantidad})`}
        )
      `;
      return res.status(200).json({ ok: true, mensaje: 'Material agendado desde WhatsApp en Neon' });
    }

    return res.status(400).json({ error: 'Tipo de operación no reconocido' });
  } catch (error) {
    console.error('Error insertando en Neon:', error);
    return res.status(500).json({ error: error.message });
  }
}
